/** Hide the quoted original generated by our reply/forward templates, without
 * changing the signature, line endings or text that is saved and sent. */
export function splitComposeQuote(body: string): { text: string; quote: string } {
  const match = /\r?\n\r?\nOn [^\r\n]+ wrote:\r?\n(?=>|$)/.exec(body);
  return match ? { text: body.slice(0, match.index), quote: body.slice(match.index) } : { text: body, quote: "" };
}
